       ["A1: MSc model (shared + identity, ordinal)", "89.53 ± 0.45", "26.45 ± 1.55", "0.9840", "99.40 ± 0.05", "1.72 ± 0.17", "0.9984"],
       ["A2: A1 without identity embedding", "86.25 ± 0.73", "34.46 ± 3.64", "0.9536", "98.44 ± 0.57", "4.71 ± 1.69", "0.9923"],
       ["A3: per-feature, ordinal categoricals", "89.63 ± 0.19", "26.23 ± 1.11", "0.9834", "99.47 ± 0.04", "1.47 ± 0.20", "0.9990"],
       ["A4: shared + categorical emb.", "89.36 ± 0.16", "27.54 ± 0.42", "0.9859", "99.32 ± 0.37", "2.04 ± 1.05", "0.9980"],
