       ["Fuzzers", "6,062", "90.23", "48.57", "89.15", "50.59"],
       ["DoS", "4,089", "99.81", "97.19", "99.94", "98.38"],
       ["Reconnaissance", "3,496", "99.86", "97.67", "99.90", "98.63"],
       ["Analysis", "677", "98.29", "94.51", "97.61", "92.38"],
       ["Backdoor", "583", "99.93", "98.90", "100.00", "99.18"],
       ["Shellcode", "378", "99.05", "88.78", "99.31", "91.22"],
