# ---- resolve citations in order of first appearance ----
order = []
def cite(m):
    keys = [k.strip() for k in m.group(1).split(",")]
    nums = []
    for k in keys:
        if k not in REFS: raise KeyError(k)
        if k not in order: order.append(k)
        nums.append(order.index(k) + 1)
    nums = sorted(set(nums)); parts = []; i = 0
    while i < len(nums):
        j = i
        while j + 1 < len(nums) and nums[j + 1] == nums[j] + 1: j += 1
        parts.append(str(nums[i]) if j == i else (f"{nums[i]},{nums[j]}" if j == i + 1 else f"{nums[i]}–{nums[j]}"))
        i = j + 1
    return "[" + ",".join(parts) + "]"
pat = re.compile(r"(?<![_^])\{([a-z][a-z_0-9]*(?:,\s*[a-z][a-z_0-9]*)*)\}")
ABSTRACT_R = ABSTRACT
for b in B:
    for key in ("x", "cap"):
        if key in b and isinstance(b[key], str): b[key] = pat.sub(cite, b[key])
    if b["t"] == "tab":
        b["rows"] = [[pat.sub(cite, c) for c in r] for r in b["rows"]]
unused = [k for k in REFS if k not in order]
spec = {"title": TITLE, "author": AUTHOR, "affil": AFFIL, "abstract": ABSTRACT_R, "keywords": KEYWORDS, "blocks": B,
        "back": BACK, "abbr": ABBR, "refs": [REFS[k] for k in order]}
